import { Activity, Crosshair, TrendingUp } from "lucide-react";
// biome-ignore lint/correctness/noUnusedImports: Storybook supports the classic JSX runtime.
import * as React from "react";
import { cn } from "@/lib/cn";
import { TraffoFeatureCard } from "@/components/jabkit/traffo-feature-card";
import { traffoFeatureItems } from "./TraffoFeaturesSection.mocks";
import type { TraffoFeaturesSectionProps } from "./TraffoFeaturesSection.types";

const fallbackIcons = [
  <Crosshair key="a" />,
  <TrendingUp key="b" />,
  <Activity key="c" />,
];

const defaults = {
  eyebrow: "02 / Built for teams",
  title: "Three pillars. One platform. Zero busywork.",
  meta: ["Version 4.2", "Shipped May 2026", "24 integrations"],
} as const;

export function TraffoFeaturesSection({
  className,
  eyebrow = defaults.eyebrow,
  title = defaults.title,
  meta = [...defaults.meta],
  items = traffoFeatureItems,
  ...props
}: TraffoFeaturesSectionProps) {
  return (
    <section
      id="features"
      data-slot="traffo-features-section"
      className={cn("bg-background text-foreground", className)}
      {...props}
    >
      <div className="mx-auto max-w-[80rem] px-[var(--jk-space-gutter)] py-[var(--jk-space-section)]">
        <div className="flex flex-col gap-8 lg:flex-row lg:items-end lg:justify-between">
          <div className="max-w-[18ch]">
            {eyebrow ? (
              <p className="font-mono text-[11px] tracking-[0.14em] text-muted-foreground uppercase">
                {eyebrow}
              </p>
            ) : null}
            <h2 className="mt-4 text-4xl font-semibold tracking-tight text-balance leading-[1.1] sm:text-6xl">
              {title}
            </h2>
          </div>
          {meta.length > 0 ? (
            <ul className="font-mono text-[11px] tracking-[0.12em] text-muted-foreground uppercase">
              {meta.map((line) => (
                <li key={line} className="leading-[1.8]">
                  {line}
                </li>
              ))}
            </ul>
          ) : null}
        </div>
        <div className="mt-12 grid gap-6 md:grid-cols-3">
          {items.map((item, index) => (
            <TraffoFeatureCard
              key={item.kicker}
              kicker={item.kicker}
              title={item.title}
              body={item.body}
              tone={item.tone}
              icon={item.icon ?? fallbackIcons[index]}
            />
          ))}
        </div>
      </div>
    </section>
  );
}

import type { HTMLAttributes, ReactNode } from "react";
import type { TraffoFeatureCardTone } from "@/components/jabkit/traffo-feature-card";

export interface TraffoFeatureItem {
  kicker: string;
  title: string;
  body: string;
  tone: TraffoFeatureCardTone;
  icon?: ReactNode;
}

export interface TraffoFeaturesSectionProps
  extends HTMLAttributes<HTMLElement> {
  eyebrow?: string;
  title?: string;
  meta?: string[];
  items?: TraffoFeatureItem[];
}

export { TraffoFeaturesSection } from "./TraffoFeaturesSection";
export type {
  TraffoFeatureItem,
  TraffoFeaturesSectionProps,
} from "./TraffoFeaturesSection.types";

import type {
  TraffoFeatureItem,
  TraffoFeaturesSectionProps,
} from "./TraffoFeaturesSection.types";

export const traffoFeatureItems: TraffoFeatureItem[] = [
  {
    kicker: "01 - Capture",
    title: "Every click. Every scroll. Every form.",
    body: "Drop the snippet, walk away. We capture every meaningful event automatically. No manual tagging, no missed data.",
    tone: "success",
  },
  {
    kicker: "02 - Understand",
    title: "Funnels, cohorts, attribution: visual.",
    body: "Drag-and-drop reports that do not require a PhD in SQL. See where users drop off, why, and what to fix first.",
    tone: "warning",
  },
  {
    kicker: "03 - Convert",
    title: "Ship experiments. Watch numbers move.",
    body: "Native A/B testing with statistical confidence baked in. Stop guessing, start shipping changes that actually compound.",
    tone: "accent",
  },
];

export const traffoFeaturesSectionMocks = {
  default: {
    eyebrow: "02 / Built for teams",
    title: "Three pillars. One platform. Zero busywork.",
    meta: ["Version 4.2", "Shipped May 2026", "24 integrations"],
    items: traffoFeatureItems,
  },
  alternate: {
    eyebrow: "Capabilities",
    title: "Measure less. Decide faster.",
    meta: ["Self-serve"],
    items: traffoFeatureItems.slice(0, 2),
  },
} satisfies Record<string, TraffoFeaturesSectionProps>;

import { type ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...classes: ClassValue[]) {
  return twMerge(clsx(classes));
}
